#include <map>
#include <set>

int main() {
    std::map<int, std::string> m;
    m.insert({10, "A"});
    m.insert({10, "B"}); // Fails, key 10 unique

    std::multimap<int, std::string> mm;
    mm.insert({20, "C"});
    mm.insert({20, "D"}); // Success, key 20 duplicated

    auto it_m = m.begin();
    // it_m->first = 5; // ERROR: Key is const and cannot be changed
    it_m->second = "NewValue"; // OK: Value is mutable
}
